  const summaryOfFacts = article.excerpt && article.excerpt.length > 30 ? article.excerpt : `Important development in ${article.category}: ${cleanTitle}. Officially published on ${article.date}.`;
  const keyTakeaways = [
    `Immediate assessment recommended for ongoing ${article.category} transactions.`,
    `Verify documentation compliance with the latest statutory guidelines.`,
    `Consult your tax advisor to update financial year reporting standards.`
  ];
  const firmPerspective = firmInsight?.trim() ? firmInsight.trim() : `At 31st File, we recommend businesses proactively analyze this update. Timely compliance safeguards your business against statutory scrutiny and unexpected penalties.`;
  const categoryTag = article.category.replace(/[^a-zA-Z0-9]/g, "");
