var router5 = (0, import_express5.Router)();
var inMemoryOverrides = [];
var nextInMemId = 1;
async function getAllOverrides() {
  if (isDbAvailable && db) {
    try {
      const records = await db.select().from(complianceOverrides).orderBy(desc(complianceOverrides.createdAt));
      return records.map((r2) => ({
        id: r2.id,
        title: r2.title,
        category: r2.category,
        originalDate: r2.originalDate,
        newDate: r2.newDate,
        note: r2.note,
        sourceUrl: r2.sourceUrl,
        createdAt: r2.createdAt
      }));
    } catch (err) {
      logger.warn({ err }, "Failed to fetch overrides from DB, using in-memory store");
    }
  }
  return inMemoryOverrides;
}
